import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"14、【大有】 乾下离上","description":"周易阐真 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"周易阐真 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/chanzhen/015.md","filePath":"zh/classics/chanzhen/015.md"}'),s={name:"zh/classics/chanzhen/015.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大有，柔得尊位大中，而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。</p></blockquote><h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><p>初九：无交害，匪咎，艰则无咎。</p><p>九二：大车以载，有攸往，无咎。</p><p>九三：公用亨于天子，小人弗克。</p><p>九四：匪其彭，无咎。</p><p>六五：厥孚交如，威如，吉。</p><p>上九：自天佑之，吉，无不利。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：火在天上，大有。君子以遏恶扬善，顺天休命。</p><p>大有者，有之大也。上离火，下乾天，是火在天上，天得日而生者众，日在天而照者远，无物不在光天化日之下，大有之象也。</p><p>君子有见于此，知天命之性，浑然一理，万善毕集，本大有也。因交后天，知识一开，先天受伤，由是善恶相杂，大有者而小有，小有者而无有矣。以是恶念一起，则遏而止息之；善念一生，则扬而滋长之，顺乎天而休美其命焉。命之不休，由于不能顺天；不顺天，由于不能遏恶扬善。若能遏恶扬善，久而至善无恶，正气常存，仍还当年完完全全天命之物事，无者有，而有者大矣。人生在世，惟命最大，有命则生，无命则死，不能休命，虽外之万有，皆属虚假。盖天之所命于人者，一善而已。能休其命，即是顺天；顺天，即所以顺命；休命，即所以休天。有天有命，有之最大。但有天有命，全在遏恶扬善工夫。遏恶扬善者，明也；顺天休命者，健也。以健为体，以明为用，虚灵不昧，具众理而应万事，由明明德而归于至善，浑然天理，性定命凝，有莫有于此，大莫大于此，世间一切身外之有，焉得而比之乎!</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>用亨，亨作享。彭，音朋。</p><p>大有者，有之大也。卦德上离明，下乾健，明以行健，健中出明，愈健愈明，愈明愈健，故谓大有。此富有日新，严以治内之卦，承上否卦而来。否者阴气用事，阳气退位，认假失真，蔽塞灵窍，日晦日暗，本来天德全无矣。若欲复还天德，无中生有，非健明之道不能。</p><p>何谓健?一念纯真，刚强不屈者是也。何谓明?烛照万事，虚灵不昧者是也。能健则心坚志远，无道不修，无德不立，而富有；能明则辨理透彻，真知确见，有善即迁，有过即改，而日新。既健且明，内有主宰，万物难移，于是真履实践，如天上有日，光照一切，无物不覆，无物能瞒，大地里黄芽长遍，满世界金花开绽，信步走去，头头是道，有之大而行之远，元而未有不亨者也。</p><p>初九，在大有之始，所有不大，正当潜修密炼，不可因外物而伤内真者，是以无交害匪咎也。然不交于外物，倘有妄念内生，亦即是物，仍是有害有咎，惟艰以处之，炼己持心，假者去而真者来，不有者能有，方能始终一无所咎矣。此初有须当静养于内也。</p><p>九二，刚健得中，已富有于内，如大车以载，能以任重，可以不为外物所伤矣。然德克于内，须验于外，惟有攸往，事上境上，轻轻过去，不动不摇，方是大有，而内外一无所咎矣。此已有须当验之于外也。</p><p>九三，刚居刚位，有之大而行之大，能以完全天德，如公用享于天子也。公用之享于天子者，刚正有为之才；修道之享于天者，刚正有为之德。以德享天，自命不凡，方且与天为配，何碍于天？</p><p>若夫刚而不正之小人，无而为有，予圣自雄，适以违天，焉能享天?此大有须贵刚之得正也。</p><p>九四，刚明兼备，有健不恃，有明不用，是匪其彭也。匪彭之刚明，外示不足，内常有余，有者愈有，大者愈大，自无得而复失之咎。此大有尤贵刚而能柔也。</p><p>六五，柔顺虚心，自信一己之无，而知他人之有，以柔求刚，借刚济柔，是以厥孚交如，威如吉也。五本无威，以其能交于刚，虽愚必明，虽柔必强，无即能有，小即能大。此未有须当求人之有也。</p><p>上九，在大有之终，刚柔相当，健明如一，浑然天理，金丹凝结，我命由我不由天，是以自天佑之，吉无不利也。</p><p>天之所以命于人者，健德；人之所以顺乎天者，明德。以明保健，天命常在，天命在而天即佑之。此大有须当全天之有也。然则大有实学，非健以治内，明以应外者不能行。既健且明，未有者而能有，已有者而能大，健明两用，实腹虚心，富有日新之道尽矣。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
